param([Parameter(Mandatory=$true)][string]$TemplatePath,[Parameter(Mandatory=$true)][string]$DataPath,[Parameter(Mandatory=$true)][string]$OutputPath,[Parameter(Mandatory=$true)][ValidateSet('xlsx','pdf')][string]$OutputFormat)
$data=Get-Content -Raw -LiteralPath $DataPath|ConvertFrom-Json
$excel=New-Object -ComObject Excel.Application;$excel.Visible=$false;$excel.DisplayAlerts=$false;$workbook=$null
try{
 $workbook=$excel.Workbooks.Open((Resolve-Path -LiteralPath $TemplatePath).Path);$sheet=$workbook.Worksheets.Item(1)
 $sheet.Range('F4').Value2=[string]$data.job_number;$sheet.Range('F5').Value2=(Get-Date).ToString('dd-MM-yyyy')
 $sheet.Range('I7').Value2=[string]$data.customer_name;$address=@($data.address,$data.city,$data.state,$data.country)|Where-Object{$_};$sheet.Range('I8').Value2=($address-join ', ')
 $sheet.Range('I12').Value2=[string]$data.meter_type;$sheet.Range('I13').Value2=[string]$data.meter_size;$sheet.Range('I14').Value2=[string]$data.manufacturer;$sheet.Range('I15').Value2=[string]$data.model_number;$sheet.Range('I16').Value2=[string]$data.mut_serial_number
 $sheet.Range('I18').Value2="$($data.flow_min) - $($data.flow_max) $($data.flow_unit)";$sheet.Range('I21').Value2=[string]$data.method_name
 $sheet.Range('I19:O19').ClearContents();$accuracyUnit=if(([string]$data.tolerance_unit)-match'\d'){'%'}else{[string]$data.tolerance_unit};$sheet.Range('I20').Value2=if($data.conformity_required){"$($data.lower_tolerance) to $($data.upper_tolerance) $accuracyUnit"}else{''};$sheet.Range('I22').Value2=[string]$data.request_date
 $sheet.Range('I23:O23').ClearContents();$sheet.Range('I24:O24').ClearContents();$sheet.Range('I25:O25').ClearContents();$sheet.Range('I26:O26').ClearContents();$sheet.Range('I28:O28').ClearContents();$sheet.Range('I29:O29').ClearContents();$sheet.PageSetup.RightFooter='Page &P of &N'
 $area=$sheet.Range('B32:O42');$area.UnMerge();$area.ClearContents();$area.Borders.LineStyle=-4142;$area.Font.Name='Times New Roman';$area.Font.Size=8
 $sheet.Range('B32:O32').Merge();$sheet.Range('B32').Value2='CALIBRATION RESULT AND CONFORMITY';$sheet.Range('B32').Font.Bold=$true;$sheet.Range('B32').Font.Color=16777215;$sheet.Range('B32').Interior.Color=4665362;$sheet.Range('B32').HorizontalAlignment=-4108
 $headers=@('Flow point','Error','Expanded U','MPE','Acceptance limit','Decision');$starts=@(2,5,7,9,11,14);$widths=@(3,2,2,2,3,2)
 for($i=0;$i-lt$headers.Count;$i++){$start=$starts[$i];$finish=$start+$widths[$i]-1;$range=$sheet.Range($sheet.Cells.Item(33,$start),$sheet.Cells.Item(33,$finish));$range.Merge();$range.Value2=$headers[$i];$range.Font.Bold=$true;$range.Interior.Color=16119274;$range.HorizontalAlignment=-4108;$range.WrapText=$true}
 $sheet.Rows.Item(33).RowHeight=24
 $row=34
 foreach($point in @($data.points)|Select-Object -First 5){$unit=if(([string]$data.tolerance_unit)-match'\d'){'%'}else{[string]$data.tolerance_unit};$flow=([double]$point.flow_value).ToString('0.###',[Globalization.CultureInfo]::InvariantCulture);$errorText=([double]$point.error_percent).ToString('+0.###;-0.###;0',[Globalization.CultureInfo]::InvariantCulture);$uncertainty=([double]$point.expanded_uncertainty).ToString('0.###',[Globalization.CultureInfo]::InvariantCulture);if($data.conformity_required){$lower=([double]$point.lower_tolerance).ToString('0.###',[Globalization.CultureInfo]::InvariantCulture);$upper=([double]$point.upper_tolerance).ToString('0.###',[Globalization.CultureInfo]::InvariantCulture);$lowerA=([double]$point.lower_acceptance).ToString('0.###',[Globalization.CultureInfo]::InvariantCulture);$upperA=([double]$point.upper_acceptance).ToString('0.###',[Globalization.CultureInfo]::InvariantCulture);$mpe="$lower$unit to $upper$unit";$acceptance="$lowerA$unit to $upperA$unit"}else{$mpe='Not requested';$acceptance='Not applicable'};$values=@("$flow $($point.flow_unit)","$errorText%","$uncertainty%",$mpe,$acceptance,[string]$point.decision);for($i=0;$i-lt$values.Count;$i++){$start=$starts[$i];$finish=$start+$widths[$i]-1;$range=$sheet.Range($sheet.Cells.Item($row,$start),$sheet.Cells.Item($row,$finish));$range.Merge();$range.Value2=$values[$i];$range.HorizontalAlignment=-4108;$range.VerticalAlignment=-4108;$range.WrapText=$true;if($i-eq 5){$range.Font.Bold=$true}};$sheet.Rows.Item($row).RowHeight=20;$row++}
 $sheet.Range($sheet.Cells.Item($row,2),$sheet.Cells.Item($row,5)).Merge();$sheet.Cells.Item($row,2).Value2='Decision rule';$sheet.Range($sheet.Cells.Item($row,6),$sheet.Cells.Item($row,15)).Merge();$sheet.Cells.Item($row,6).Value2=if($data.conformity_required){"$($data.rule_code) Rev. $($data.rule_revision) - Guarded acceptance, w=U"}else{'Not applicable - conformity statement not requested'};$row++
 $sheet.Range($sheet.Cells.Item($row,2),$sheet.Cells.Item(42,5)).Merge();$sheet.Cells.Item($row,2).Value2='Statement';$sheet.Cells.Item($row,2).VerticalAlignment=-4160;$sheet.Range($sheet.Cells.Item($row,6),$sheet.Cells.Item(42,15)).Merge();$sheet.Cells.Item($row,6).Value2=[string]$data.statement_text;$sheet.Cells.Item($row,6).WrapText=$true;$sheet.Cells.Item($row,6).VerticalAlignment=-4160
 $sheet.Range('B32:O42').Borders.LineStyle=1;$sheet.Range('B32:O42').Borders.Weight=2
 $absolute=[IO.Path]::GetFullPath($OutputPath);if($OutputFormat-eq'xlsx'){$workbook.SaveAs($absolute,51)}else{$workbook.ExportAsFixedFormat(0,$absolute)};$workbook.Close($false);$workbook=$null
}finally{if($workbook){$workbook.Close($false)};$excel.Quit();[Runtime.InteropServices.Marshal]::FinalReleaseComObject($excel)|Out-Null}
